import numpy as np

def advanced_matrix_ops():
    '''
    Uses the global computation_cache containing previous matrix multiplication results.
    For each result matrix, if it is square, computes its eigenvalues and returns
    a dict mapping cache keys to their eigenvalues as lists.
    '''
    global computation_cache  # ensure we access the external/global variable

    eigen_cache = {}

    for key, matrix in computation_cache.items():
        # Check if the matrix is square
        if isinstance(matrix, list) and matrix:
            n_rows = len(matrix)
            if all(isinstance(row, list) and len(row) == n_rows for row in matrix):
                # Convert to numpy array for eigenvalue calculation
                np_matrix = np.array(matrix)
                try:
                    eigenvalues = np.linalg.eigvals(np_matrix)
                    # Convert numpy array to list for nicer output
                    eigen_cache[key] = eigenvalues.tolist()
                except Exception as e:
                    eigen_cache[key] = f"Error computing eigenvalues: {str(e)}"
            else:
                eigen_cache[key] = "Matrix not square"
        else:
            eigen_cache[key] = "Invalid matrix"
    return eigen_cache

