    if not sensor_str or "T:" not in sensor_str:
        return {'temperature': None, 'humidity': None}
    try:
        parts = sensor_str.split(";")
        temp = None
        for part in parts:
            if part.startswith("T:"):
                tempval = part.split(":")[1]
                # Special case: allow 'None' string
                if tempval.strip().lower() == "none":
                    temp = None
                else:
                    temp = float(tempval)
        return {'temperature': temp}
    except Exception:
